def validate_scripts(scripts):
    """Rule 7 (No ellipsis) and Rule 9 (Tech terms)."""
    errors = []
    for idx, s in enumerate(scripts):
        sid = s["id"]
        # Rule 7 Check
        for t_idx, turn in enumerate(s["turns"]):
            spk, phrases, photo = turn
            for p_idx, (disp, spok) in enumerate(phrases):
                if "..." in disp or "…" in disp or "..." in spok or "…" in spok:
                    errors.append(f"[{sid}] Turn {t_idx} phrase {p_idx} has ellipsis!")
        # Headlines Check
        for h in s["headlines"]:
            if "..." in h["sub"] or "..." in h["t"] or "..." in h["hl"]:
                errors.append(f"[{sid}] Headline has ellipsis!")
        # CTA Check
        if "..." in s["cta"] or "…" in s["cta"]:
            errors.append(f"[{sid}] CTA has ellipsis!")
    return errors

def main():
    print(f"Validating {len(SCRIPTS)} GOOJODOQ couple scripts...")
    errors = validate_scripts(SCRIPTS)
    if errors:
        print("❌ Validation errors found:")
        for e in errors:
            print(f"  - {e}")
        return False
    print("✅ All 20 scripts passed Zero-Ellipsis & Persona validation!")

    # 1. Save JSON catalog
    json_path = DOCS / "goojodoq_5000mah_20_scripts.json"
    with open(json_path, "w", encoding="utf-8") as f:
        json.dump(SCRIPTS, f, ensure_ascii=False, indent=2)
    print(f"Saved JSON catalog to: {json_path}")

    # 2. Save Markdown catalog
    md_path = DOCS / "goojodoq_5000mah_20_scripts.md"
    with open(md_path, "w", encoding="utf-8") as f:
        f.write("# 📱 GOOJODOQ 5000mAh Mini Power Bank — Master Scripts Catalog (20 บทสไตล์คู่รักสายใต้)\n\n")
        f.write("> **สไตล์คลิป:** #5 Couple Paper Chat (กระดาษยับ)\n")
        f.write("> **ตัวละคร:** น้องนุ้ย (F - Aoede / สาวใต้ขี้บ่นดุแต่น่ารัก) & พี่บ่าว (M - Puck / ซื่อๆ กวนๆ โดนแฟนยึดของ)\n")
        f.write("> **กฎเหล็ก:** Zero-Ellipsis 100% (ไร้จุดไข่ปลา), คำศัพท์เทคนิคถูกต้อง (GOOJODOQ, iPhone, Type-C, Lightning, 5000mAh, LED, USB-A), Micro-burst 2-4 คำ\n")
        f.write("> **สินค้า:** GOOJODOQ มินิพาวเวอร์แบงค์แคปซูล 5000mAh (2 หัวในตัว + ขาตั้งในตัว + 2 Input)\n\n")
        f.write("---\n\n")

        for idx, s in enumerate(SCRIPTS):
            f.write(f"## บทที่ {idx+1}: {s['title']} (`{s['id']}`)\n")
            f.write(f"- **หมวดหมู่:** {s['category']}\n")
            f.write(f"- **สถานการณ์:** {s['scenario']}\n")
            f.write(f"- **Hook Title:** `{s['hook_title']}`\n\n")
            
            f.write("### 📌 หัวข้อป้ายยา (Headlines Overlays)\n")
            for h in s['headlines']:
                f.write(f"- **Turn {h['turn']}:** Sub: `{h['sub']}` | Title: `{h['t']}` | Highlight: `{h['hl']}`\n")
            f.write("\n")
            
            f.write("### 💬 บทสนทนา (Dialogue Breakdown)\n\n")
            f.write("| เทิร์น | ผู้พูด | ข้อความบนหน้าจอ (Display) | เสียงพากย์ (Spoken) | รูปสินค้า |\n")
            f.write("| :---: | :---: | :--- | :--- | :---: |\n")
            
            for t_idx, turn in enumerate(s['turns']):
                spk, phrases, photo = turn
                spk_name = "น้องนุ้ย (F)" if spk == "F" else "พี่บ่าว (M)"
                disp_str = " <br> ".join([p[0] for p in phrases])
                spok_str = " <br> ".join([p[1] for p in phrases])
                photo_str = f"มีรูป ({photo[2]})" if photo else "-"
                f.write(f"| {t_idx+1} | {spk_name} | {disp_str} | {spok_str} | {photo_str} |\n")
                
            f.write(f"\n**📣 CTA ปิดคลิป:** `{s['cta']}`\n\n")
            f.write("---\n\n")
            
    print(f"Saved Markdown catalog to: {md_path}")
    
    # 3. Sync to _Docs/products.json
    sync_to_products_json(SCRIPTS)
    return True

def sync_to_products_json(scripts):
    from datetime import datetime
    products_file = DOCS / "products.json"
    if not products_file.exists():
        print("❌ products.json not found!")
        return
    with open(products_file, "r", encoding="utf-8") as f:
        products = json.load(f)
    
    # Target GOOJODOQ product
    p_target = next((p for p in products if p.get("product_code") == "GOO01" or "1731584286163241762" in str(p.get("tiktok_product_id", ""))), None)
    if not p_target:
        print("❌ Target GOOJODOQ product not found in products.json!")
        return
        
    p_target["status"] = "scripted"
    existing_aids = {a.get("angle_id") for a in p_target.get("angles", [])}
    now_str = datetime.now().isoformat(timespec="seconds")
    added = 0
    
    for s in scripts:
        aid = s["id"]
        if aid in existing_aids:
            continue
        script_text = "\n".join([
            f"{'น้องนุ้ย (F)' if t[0]=='F' else 'พี่บ่าว (M)'}: {' '.join(p[1] for p in t[1])}"
            for t in s["turns"]
        ])
        new_angle = {
            "angle_id": aid,
            "angle_name": f"💬 ละครคู่รัก: {s['title']}",
            "title": s["title"],
            "hook_title": s["hook_title"],
            "status": "script_ready",
            "draft_type": "hyperframes",
            "style": "couple_paper_chat",
            "category": s["category"],
            "scenario": s["scenario"],
            "duration": "48-55s",
            "turns_count": len(s["turns"]),
            "script_text": script_text,
            "script_lines": [p[0] for t in s["turns"] for p in t[1]],
            "headlines": s["headlines"],
            "turns": s["turns"],
            "cta": s["cta"],
            "tiktok_caption": f"{s['hook_title']} GOOJODOQ มินิพาวเวอร์แบงค์แคปซูล 5000mAh มี 2 หัวในตัว ไม่ต้องพกสาย มีขาตั้งในตัว พิกัดในตะกร้าเหลืองเลย 👇",
            "tiktok_hashtags": "#GOOJODOQ #พาวเวอร์แบงค์จิ๋ว #พาวเวอร์แบงค์แคปซูล #TikTokป้ายยา #พิกัดในตะกร้า",
            "created_at": now_str,
            "updated_at": now_str
        }
        p_target.setdefault("angles", []).append(new_angle)
        added += 1
        
    with open(products_file, "w", encoding="utf-8") as f:
        json.dump(products, f, ensure_ascii=False, indent=2)
    print(f"Synced {added} new angles into _Docs/products.json for GOO01 (Total angles: {len(p_target['angles'])})")

if __name__ == "__main__":
    main()
